class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def info(self):
        return f"{self.name}: {self.salary}"

class Manager(Employee):
    def __init__(self, name, salary, team_size):
        super().__init__(name, salary)
        self.team_size = team_size

    def info(self):
        base = super().info()
        return f"{base}, в подчинении {self.team_size}"

boss = Manager("Ирина", 300000, 7)
print(boss.info())                 # Ирина: 300000, в подчинении 7
print(isinstance(boss, Employee))  # True

class Money:
    def __init__(self, amount, currency="RUB"):
        self.amount = amount
        self.currency = currency

    def __str__(self):
        return f"{self.amount} {self.currency}"

    def __repr__(self):
        return f"Money({self.amount!r}, {self.currency!r})"

price = Money(1200)
print(price)      # 1200 RUB — print использует __str__
print([price])    # [Money(1200, 'RUB')] — список печатает __repr__ элементов
print(repr(price))  # Money(1200, 'RUB')

class Playlist:
    def __init__(self, title, tracks):
        self.title = title
        self.tracks = list(tracks)

    def __len__(self):
        return len(self.tracks)

    def __eq__(self, other):
        if not isinstance(other, Playlist):
            return NotImplemented
        return self.title == other.title and self.tracks == other.tracks

morning = Playlist("Утро", ["Yesterday", "Hey Jude"])
print(len(morning))                                # 2
print(morning == Playlist("Утро", ["Yesterday", "Hey Jude"]))  # True
print(morning == Playlist("Вечер", ["Yesterday", "Hey Jude"])) # False

