class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return f"{self.name} издаёт звук"


class Dog(Animal):
    def speak(self):
        return f"{self.name} говорит гав"


class Puppy(Dog):
    def __init__(self, name, age):
        super().__init__(name)
        self.age = age

    def speak(self):
        return f"{self.name} ({self.age} мес.) говорит гав"


beast = Animal("Зверь")
print(beast.speak())
rex = Dog("Рекс")
print(rex.speak())
print(isinstance(rex, Animal))
bim = Puppy("Бим", 3)
print(bim.speak())
print(bim.name)

class Book:
    def __init__(self, title, pages):
        self.title = title
        self.pages = pages

    def __str__(self):
        return f"«{self.title}» — {self.pages} стр."

    def __repr__(self):
        return f"Book({self.title!r}, {self.pages})"

    def __len__(self):
        return self.pages

    def __eq__(self, other):
        if not isinstance(other, Book):
            return NotImplemented
        return self.title == other.title and self.pages == other.pages


book = Book("Мастер и Маргарита", 480)
print(book)
print(repr(book))
print(len(book))
print(book == Book("Мастер и Маргарита", 480))
print(book == Book("451 градус по Фаренгейту", 480))
print([Book("Колобок", 32)])
